seed.new:
for (const signal of ['SIGINT', 'SIGTERM']) process.once(signal, async () => {
  await companion.close();
  // Leave no temporary project-list files behind after an interrupted save.
  const state = path.dirname(preferencesPath);
  for (const name of await readdir(state).catch(() => [])) {
    if (name.startsWith(path.basename(preferencesPath))) await rm(path.join(state, name), { force: true });
  }
  process.exit(0);
});
